# area: protocols
# hypothesis: A class with only a read-only property does not satisfy a Protocol with a settable attribute, and an unrelated class without a method does not get the Protocol's default body, so both marked calls must be rejected.
from typing import Protocol, TypeVar, reveal_type

T = TypeVar('T')


class HasName(Protocol):
    @property
    def name(self) -> str: ...


class Settable(Protocol):
    name: str


class Greeter(Protocol):
    def greet(self) -> str:
        return 'hi'


class Box(Protocol[T]):
    def get(self) -> T: ...


class Plain:
    def __init__(self, name: str) -> None:
        self.name = name


class ReadOnly:
    @property
    def name(self) -> str:
        return 'ro'


class Quiet:
    pass


class Explicit(Greeter):
    pass


class IntBox:
    def __init__(self, v: int) -> None:
        self._v = v

    def get(self) -> int:
        return self._v


def show_name(obj: HasName) -> str:
    return obj.name


def set_name(obj: Settable) -> None:
    obj.name = 'new'


def greet_with(g: Greeter) -> str:
    return g.greet()


def unbox(b: Box[T]) -> T:
    return b.get()


def probe() -> None:
    reveal_type(show_name(Plain('a')))
    print(show_name(Plain('a')), show_name(ReadOnly()))
    set_name(Plain('b'))
    try:
        set_name(ReadOnly())  # expect-error: read-only property is not a settable attribute
    except (AttributeError, TypeError) as exc:
        print('readonly:', type(exc).__name__)
    print(greet_with(Explicit()))
    try:
        print(greet_with(Quiet()))  # expect-error: Quiet lacks greet, default body not inherited
    except (AttributeError, TypeError) as exc:
        print('quiet:', type(exc).__name__)
    reveal_type(unbox(IntBox(4)))
    print(unbox(IntBox(4)))


probe()
